class MigrationRunner
{
    // Fixed: EF Core 9 manages its own transactions and execution strategy
    // during Migrate(). Wrapping in an explicit transaction now throws.
    void ApplyMigrations(AppDbContext db)
    {
        db.Database.Migrate();
    }
}

